```json
// AWS ECR Lifecycle Policy: expire ephemeral PR builds after 7d, keep last 50 releases
{
  "rules": [
    {
      "rulePriority": 1,
      "description": "Expire ephemeral PR images after 7 days",
      "selection": {
        "tagStatus": "tagged",
        "tagPrefixList": ["pr-", "dev-"],
        "countType": "sinceImagePushed",
        "countUnit": "days",
        "countNumber": 7
      },
      "action": { "type": "expire" }
    },
    {
      "rulePriority": 2,
      "description": "Retain last 50 immutable release tags",
      "selection": {
        "tagStatus": "tagged",
        "tagPrefixList": ["v"],
        "countType": "imageCountMoreThan",
        "countNumber": 50
      },
      "action": { "type": "expire" }
    }
  ]
}
```
